import * as dotenv from 'dotenv';
import { join } from 'path';
import { defineConfig } from 'prisma/config';

const envFiles = [join(process.cwd(), '.env'), join(process.cwd(), 'backend', '.env')];
for (const envPath of envFiles) {
  dotenv.config({ path: envPath, override: false });
}

let migrationUrl = process.env['DIRECT_URL'] || process.env['DATABASE_URL'] || '';
// Utilisation directe de DATABASE_URL (supporte le pooler 6543)


export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: {
    path: 'prisma/migrations',
  },
  datasource: {
    url: migrationUrl,
    // @ts-ignore
    directUrl: migrationUrl,
  },
});
